use anyhow::{Context,Result,bail};use fluxvm_intelligence::tcpintel::{self,DEFAULT_TCP_PIN_ROOT,DEFAULT_TCP_STATE_ROOT};use std::{env,path::PathBuf};use uuid::Uuid;
fn usage()->&'static str{"fluxvm-tcpintel commands:\n  attach <uuid> <iface> [sample_rate]\n  snapshot <uuid> [flow_limit]\n  metrics <uuid>\n  events <uuid> [seconds] [limit]\n  detach <uuid>\nenv: FLUXVM_TCP_PIN_ROOT FLUXVM_TCP_STATE_ROOT FLUXVM_TCP_LOADER FLUXVM_TCP_OBJECT"}
fn main()->Result<()>{let a:Vec<String>=env::args().collect();let pin=env::var("FLUXVM_TCP_PIN_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_TCP_PIN_ROOT.into());let state=env::var("FLUXVM_TCP_STATE_ROOT").map(PathBuf::from).unwrap_or_else(|_|DEFAULT_TCP_STATE_ROOT.into());match a.get(1).map(String::as_str){Some("attach")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;let iface=a.get(3).context(usage())?;let sample=a.get(4).and_then(|v|v.parse().ok()).unwrap_or(100);println!("{}",serde_json::to_string_pretty(&tcpintel::attach(id,iface,sample,&pin,&state)?)?);Ok(())},Some("snapshot")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;let lim=a.get(3).and_then(|v|v.parse().ok()).unwrap_or(128);println!("{}",serde_json::to_string_pretty(&tcpintel::snapshot(id,&pin,&state,lim)?)?);Ok(())},Some("metrics")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;print!("{}",tcpintel::prometheus(&tcpintel::snapshot(id,&pin,&state,1)?));Ok(())},Some("events")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;let sec=a.get(3).and_then(|v|v.parse().ok()).unwrap_or(5);let lim=a.get(4).and_then(|v|v.parse().ok()).unwrap_or(128);tcpintel::stream_events(id,&pin,sec,lim)},Some("detach")=>{let id:Uuid=a.get(2).context(usage())?.parse()?;tcpintel::detach(id,&pin,&state)?;println!("{{\"detached\":true,\"vm_id\":\"{id}\"}}");Ok(())},_=>bail!(usage())}}
